import React, { useEffect } from "react";
import { Divider } from "antd";
import styled, { keyframes } from "styled-components";
import Flower from "../assets/flower2.png";

const Wrapper = styled.div`
  padding-top: 42px;
  width: 70%;
  margin: 0 auto;
`;

const Title = styled.span`
  font-size: 2.2rem;
  color: var(--title-color);
  font-weight: bold;
  opacity: 1.0;
  margin-bottom: 0;
  text-align: center;
  font-family: "mom_to_daughter";
`;

const Image = styled.img`
  display: block;
  margin: 0 auto;
  width: 1.375rem;
  padding-bottom: 42px;
`;

const Content = styled.p`
  font-size: 0.875rem;
  line-height: 1.75;
  opacity: 0.75;
  width: 100%;
  text-align: center;
  padding-top: 42px;
  padding-bottom: 42px;
  margin: 0;
`;

const shine = keyframes`
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
`;

const MapWrapper = styled.div`
  width: 100%;
  padding: 3px;
  border-radius: 20px;
  background: linear-gradient(270deg, #eda6ab, #eda6ab, #eda6ab);
  background-size: 200% 200%;
  animation: ${shine} 5s ease-in-out infinite;
  box-sizing: border-box;
  margin-bottom: 42px;
`;

const Map = styled.div`
  width: 100%;
  height: 360px;
  border-radius: 17px;
  overflow: hidden;
`;

const AddCalendarButton = styled.button`
  display: block;
  margin: 16px auto 40px auto;
  background: linear-gradient(90deg, #eda6ab, #eda6ab);
  color: white;
  border: none;
  border-radius: 30px;
  padding: 8px 18px;
  font-size: 0.8rem;
  font-weight: bold;
  box-shadow: 0 3px 6px rgba(0, 0, 0, 0.2);
  transition: all 0.3s ease;
  cursor: pointer;

  &:hover {
    transform: scale(1.05);
    box-shadow: 0 0 10px rgba(255, 192, 203, 0.6);
  }
`;

const Location = () => {
  const executeScript = () => {
    const scriptTag = document.createElement("script");
    const inlineScript = document.createTextNode(`new daum.roughmap.Lander({
		"timestamp" : "1762596796223",
		"key" : "btu5ov8miud",
		"mapWidth" : "640",
		"mapHeight" : "360"
    }).render();`);
    scriptTag.appendChild(inlineScript);
    document.body.appendChild(scriptTag);
  };

  const InstallScript = () => {
    (function () {
      let c = window.location.protocol === "https:" ? "https:" : "http:";
      let a = "16137cec";

      if (window.daum && window.daum.roughmap && window.daum.roughmap.cdn) {
        return;
      }
      window.daum = window.daum || {};
      window.daum.roughmap = {
        cdn: a,
        URL_KEY_DATA_LOAD_PRE: c + "//t1.daumcdn.net/roughmap/",
        url_protocal: c,
      };
      let b =
        c +
        "//t1.daumcdn.net/kakaomapweb/place/jscss/roughmap/" +
        a +
        "/roughmapLander.js";

      const scriptTag = document.createElement("script");
      scriptTag.src = b;
      document.body.appendChild(scriptTag);
      scriptTag.onload = () => {
        executeScript();
      };
    })();
  };

  useEffect(() => {
    InstallScript();
  }, []);

  // 📅 캘린더 버튼 클릭 시 항상 .ics 다운로드
const handleAddToCalendar = () => {
  const icsContent =
"BEGIN:VCALENDAR\r\n" +
"VERSION:2.0\r\n" +
"BEGIN:VEVENT\r\n" +
"SUMMARY:데이트♡\r\n" +
"DESCRIPTION:우리의 특별한 데이트 시간 💕\r\n" +
"LOCATION:서울특별시 영등포구 63로 50, 63빌딩 58층 Touch the Sky\r\n" +
"DTSTART:20251207T173000\r\n" +  // KST 시간 그대로 사용
"DTEND:20251207T193000\r\n" +    // KST 시간 그대로 사용
"END:VEVENT\r\n" +
"END:VCALENDAR\r\n";

  const blob = new Blob([icsContent], { type: "text/calendar;charset=utf-8" });
  const link = document.createElement("a");
  link.href = URL.createObjectURL(blob);
  link.download = "데이트_일정.ics";
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};
  return (
    <Wrapper>
      <Divider plain style={{ marginTop: 0, marginBottom: 32 }}>
        <Title>이번 데이트 장소는</Title>
      </Divider>

      <Image src={Flower} />

      <MapWrapper>
        <Map
          id="daumRoughmapContainer1762596796223"
          className="root_daum_roughmap root_daum_roughmap_landing"
        ></Map>
      </MapWrapper>

      <Content>
        서울특별시 영등포구 63로 50 
        <br />
        63빌딩 58층 
        <br />
        <br />
        🎆 Touch the Sky 🎆
        <br />
        <br />
        <br />
        <br />
        <Title>언제냐면...</Title>
        <br />
        <br />
        12월 7일 (일요일) 오후 5시 30분
      </Content>

      {/* 📅 캘린더 등록 버튼 */}
      <AddCalendarButton onClick={handleAddToCalendar}>
        📆 달력에 적어놓기 📆
      </AddCalendarButton>
      <br />

      <Content>
        <Title>가는 방법은!</Title>
        <br />
        <br />
        자차 보유한 미모의 30대 남성 대기 중...
        <br />
        Tel) 010-9025-9501 ☎
      </Content>
    </Wrapper>
  );
};

export default Location;