import React from "react";
import styled from "styled-components";
import {
  WEDDING_DATE,
  WEDDING_LOCATION,
  GROOM_NAME,
  BRIDE_NAME,
} from "../../config.js";
import BackgroundVideo from "../assets/BackgroundVideo.mp4";
import GroovePaper from "../assets/GroovePaper.png";
import Flower from "../assets/dog.png";

const FooterImage = styled.img`
  display: block;
  margin: 20px auto 0; /* 상단 마진 20px, 좌우 중앙 정렬 */
  width: 200px;          /* 원하는 크기로 조정 */
`;


const Layout = styled.div`
  width: 90%;
  overflow: hidden;
  margin: 0 auto;
`;

const TitleWrapper = styled.div`
  width: 100%;
  text-align: center;
  padding-top: 42px;
  font-weight: 500 !important;
  color: var(--title-color);
  animation: fadein 3s;
  -moz-animation: fadein 3s; /* Firefox */
  -webkit-animation: fadein 3s; /* Safari and Chrome */
  -o-animation: fadein 3s; /* Opera */
`;

const VideoBackground = styled.video`
  width: 100%;
  border-radius: 20px; /* 모서리 둥글게 */
  overflow: hidden;    /* 비디오가 라운딩 밖으로 나가지 않도록 */
`;

const WeddingInvitation = styled.p`

  font-size: 0.925rem;
  opacity: 0.85;
  margin-bottom: 16px;
`;

const GroomBride = styled.p`
  font-size: 3.5rem;
  font-family: "mom_to_daughter";

  font-weight: bold;
  opacity: 0.9;
  margin-bottom: 16px;
`;

const Schedule = styled.p`
  font-size: 1.16rem;
  opacity: 0.85;
  margin-bottom: 24px;
`;
const Title = () => {
  return (
    <Layout>
      <TitleWrapper>
        <WeddingInvitation>새삼스럽지만, 자기에게 하는</WeddingInvitation>
        <GroomBride>
           데이트 신청
        </GroomBride>

      </TitleWrapper>

      <FooterImage src={Flower} alt="꽃 이미지" />
     <br />

      <VideoBackground autoPlay loop muted playsInline={true}>
        <source src={BackgroundVideo} type="video/mp4" />
      </VideoBackground>
     <br />
     <br />


    </Layout>
  );
};

export default Title;
